-- =============================================================================================
-- Hand-written below this line
-- =============================================================================================

ALTER TABLE audit.audit_log
  ADD CONSTRAINT audit_log_action_format CHECK (action ~ '^[a-z_]+(\.[a-z_]+)+$');

-- Append-only (Backend Schema 11.1): no UPDATE, DELETE or TRUNCATE, for anyone.
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit.audit_log
  FOR EACH ROW EXECUTE FUNCTION app.forbid_change();
CREATE TRIGGER audit_no_truncate BEFORE TRUNCATE ON audit.audit_log
  FOR EACH STATEMENT EXECUTE FUNCTION app.forbid_change();

-- Row level security (Backend Schema 10.3): insert and read within the organization;
-- platform admins read everything and may write platform-level (NULL organization) entries.
ALTER TABLE audit.audit_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_insert ON audit.audit_log FOR INSERT TO vk_api
  WITH CHECK (organization_id IS NOT DISTINCT FROM app.current_org_id() OR app.is_platform_admin());
CREATE POLICY audit_select ON audit.audit_log FOR SELECT TO vk_api
  USING (organization_id = app.current_org_id() OR app.is_platform_admin());

-- Grants (Backend Schema 10.4): INSERT and SELECT only; never UPDATE, DELETE or TRUNCATE.
GRANT INSERT, SELECT ON audit.audit_log TO vk_api;
GRANT SELECT ON audit.audit_log TO vk_readonly;
